    /**This method sets the socket picket out for the request processing.
     * It gets the input stream from socket and creates the output stream.
     * @param socket the socket picked out for this connection.
     */
    public void setSocket(Socket socket) {
        super.setSocket(socket);
        try {
            inputStream.init(socket.getInputStream());
            outputStream = socket.getOutputStream();
        } catch (IOException ioex) {
            //Logger.log("Cannot get input stream from socket", ioex, 1);
            cat.error("Cannot get input stream from socket", ioex);
            good = false;
            return;
        }
    }

    /**This method parses the request or doing nothing if there is no input
     * stream or output stream associated with the socket.
     */
    public void parse() {
        //Checks if there are input, output streams available.
        if (inputStream == null || outputStream == null) {
            //Logger.log("Invalid socket", 1);
            cat.error("Invalid socket");
            good = false;
            return;
        }
        reqTime = HttpDate.getCurrentDate4log();
        try {
            inputStream.readRequestLine(requestLine);
        } catch (IOException ioex) {
            //Logger.log(ioex, -1);
            cat.debug("Cannot read request line", ioex);
            good = false;
            return;
        }


        if (requestLine.uri.equals(star)) {
            processServerRequest();
            good = false;
            return;
        }
        if (requestLine.uri.startsWith(httpStart)) {
            requestURI = requestLine.uri.toString();
            int index = requestURI.indexOf('/', 8);
            host = index > -1
                    ? requestURI.substring(7, index)
                    : requestURI.substring(7, requestURI.length());
            requestURI = index > -1
                    ? requestURI.substring(index, requestURI.length())
                    : "/";
        }
        String jsession = requestLine.uri.cutToEnd(sessionChars, false);
        if (jsession != null) {
            request.setSessionIdFromURL(jsession);
        }
        try {
            headers.read(inputStream);
        } catch (IOException ioex) {
            //Logger.log("Error occured while processing headers", ioex, 1);
            cat.debug("Error occured while processing headers", ioex);
            good = false;
            errorCode = HttpServletResponse.SC_BAD_REQUEST;
            writeError();
            return;
        }

        successfullyParsed = true;
        keepAlive = !isStandAlone();
    }

    /**This method sends response with the error message.
     */
    private void writeError(Exception ex) {
        //    System.out.println("!!!!!!!!!!!!!!!!!!!1");
        try {
            servletOutput.init(outputStream);
            response.init(servletOutput, keepAlive);
            if (!isStandAlone()) {
                //        response.setContainerID(containerID);
            }
            if (ex != null) {
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                PrintStream ps = new PrintStream(baos);
                ex.printStackTrace(ps);
                ps.flush();
                Exception exception = null;
                if (ex instanceof ServletException) {
                    exception = (Exception) ((ServletException) ex).getRootCause() == null
                            ? exception
                            : (Exception) ((ServletException) ex).getRootCause();
                } else {
                    exception = ex;
                }
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR,
                        baos.toString());
            } else {
                response.sendError(errorCode);
            }
        } catch (IOException ioex) {
            //Logger.log("Error occured while writing error", ioex, 1);
            //      cat.error("Error occured while writing error");
        }
    }

    private void writeError() {
        writeError(null);
    }

