    /**This method takes the error code number and then sends response with
     * the error message and then closes connection socket.
     * @param error error code.
     */
    public void processError(int error) {
        processError(error, null);
    }

    public void processError(int error, Exception ex) {
        switch (error) {
            case ERROR_SERVLET_NOT_FOUND:
                errorCode = 404;
                break;
            case ERROR_OK:
                errorCode = 200;
                break;
            case ERROR_FORBIDDEN:
                errorCode = 403;
                break;
            case ERROR_UNAUTHORIZED:
                errorCode = 401;
                processUnauthorizedError(true);
                break;
            case ERROR_AUTHENTICATION_FAILED:
                errorCode = 401;
                processUnauthorizedError(false);
                break;
            case ERROR_CANNOT_INIT_SERVLET:
            case ERROR_HANDLER_INTERNAL:
            case ERROR_SERVLET_REPORTED:
            default:
                errorCode = 500;
                break;
        }
        if (error != ERROR_UNAUTHORIZED && error != ERROR_AUTHENTICATION_FAILED)
            writeError(ex);
        /*    try {
         socket.close();
         } catch (IOException ioex) {
         //Logger.log("Error occured while closing socket", ioex, 1);
         cat.error("Error occured while closing socket");
         }*/
    }

