    /**
     * This method process unauthorized error.
     * @param isLoginPageNeeded True if login page needed for user.
     */
    private void processUnauthorizedError(boolean isLoginPageNeeded) {
        NusuthContext currContext = getContext();
        switch (currContext.getDefaultAuthType()) {
            case AuthenticationData.AUTH_METHOD_FORM:
                String formPage = isLoginPageNeeded
                        ? getContext().getFormLoginPage().toString()
                        : getContext().getFormErrorPage().toString();
                if (isLoginPageNeeded)
                    saveRequest();
                try {
                    String url = this.getScheme() + "://" + getServerHost() + ':'
                            + getServerPort() + this.getContextPath();
                    url += formPage.startsWith("/") ? formPage : '/' + formPage;
                    if (!isLoginPageNeeded) {
                        RequestDispatcher disp
                                = request.getRequestDispatcher(formPage.startsWith("/") ? formPage : '/' + formPage);
                        response.reset();
                        response.setStatus(401);
                        try {
                            disp.include(request, response);
                        } catch (ServletException e) {
                            cat.error("Caanot send error page", e);
                        }
                    } else {
                        sendRedirect(url);
                    }
                } catch (IOException ioex) {
                    //cat.error("Error occured while requesting user authentication");
                }
                break;
            case AuthenticationData.AUTH_METHOD_CERT:
                // not implemented
            case AuthenticationData.AUTH_METHOD_DIGEST:
                // not implemented
            case AuthenticationData.AUTH_METHOD_BASIC:
            default:
                servletOutput.init(outputStream);
                response.init(servletOutput, keepAlive);
                response.reset();
                response.setHeader("WWW-Authenticate",
                        "Basic realm=" + getContext().getAuthRealm());
                response.setContentType("text/html");
                response.setStatus(errorCode);
                try {
                    response.getOutputStream().println("<HTML><TITLE>Unauthorized"
                            + "</TITLE><BODY><H1>401 "
                            + "Unauthorized</H1><br>"
                            + "<pre>Unauthorized</pre>"
                            + "</BODY></HTML>");
                } catch (IOException ioex) {
                    //cat.error("Error occured while requesting user authentication");
                }
                break;
        }
    }

    /**This method creates the request object and sets all it's attributes such
     * as servlet path , servlet name,
     * method name, scheme name etc.... It also creates response object.
     * @param context the @see NusuthContext defined by the request URL.
     * @param contextPath the path to the web application context(defined by
     * the request URL) in the jndi context.
     */
    public ContainerInvocationCacheElement setContext(NusuthContext context,
                                                      String contextPath) {
        if (requestURI == null) {
            requestURI = requestLine.uri.toString();
        }
        String path = requestURI.substring(requestURI.indexOf(contextPath)
                + contextPath.length());
        if (!path.startsWith("/")) {
            path = "/" + path;
        }
        Object[] chain = null;
        chain = context.findResourceChain(path);
        if (chain == null) {
            cat.error("Cannot find servlet for path " + path
                    + ", request URI: " + requestURI);
            good = false;
            errorCode = HttpServletResponse.SC_NOT_FOUND;
            writeError();
            return null;
        }
//    String servletPath = fserv[0];
//    String servletName = fserv[1];
        String servletPath = null;
//    if (((ResourceChain)chain[1]).getServletPath().startsWith("*.")) {
        servletPath = (String) chain[0];
//    } else {
//      servletPath = ((ResourceChain)chain[1]).getServletPath();
//    }
        String servletName = ((ResourceChain) chain[1]).getServletName();
        String pathInfo
                = requestURI.substring(requestURI.indexOf(contextPath + servletPath)
                + (contextPath + servletPath).length(),
                        requestURI.length());
        ContainerInvocationCacheElement cacheElement
                = new ContainerInvocationCacheElement();
        cacheElement.context = context;
        cacheElement.chain = (ResourceChain) chain[1];
        cacheElement.contextPath = new StrBuffer(32);
        cacheElement.contextPath.append(contextPath);
        cacheElement.pathInfo = new StrBuffer(32);
        cacheElement.pathInfo.append(pathInfo);
        cacheElement.servletName = servletName;
        cacheElement.servletPath = new StrBuffer();
        cacheElement.servletPath.append(servletPath);
        setContext(cacheElement);
        return cacheElement;
    }

    public void setContext(ContainerInvocationCacheElement cacheElement) {
        this.cacheElement = cacheElement;
        NusuthServletInputStream is = retreiveInputStream();
        if (is == null) {
            //Logger.log("Internal error: undefined method", 1);
            cat.error("Internal error: undefined method");
            good = false;
            return;
        }
        request.init(is);
        servletName = cacheElement.servletName;
        keepAlive = isKeepAliveAllowed() && (!isStandAlone() ||
                (requestLine.protocol.equals(http11)
                && !headers.containsHeader(HttpConstants.CONNECTION,
                        HttpConstants.CLOSE)));
        //creates response object
        servletOutput.init(outputStream);
        response.init(servletOutput, keepAlive);
        if (requestLine.method.equals(HttpConstants.METHOD_HEAD)) {
            response.setBodySend(false);
        }
        response.setRequest(request);
        request.setSessionCreationListener(response);
        if (!isStandAlone()) {
            Cookie[] cookies = request.getCookies();
            boolean needContainerId = true;
            if (cookies != null) {
                for (int i = 0; i < cookies.length; i++) {
                    if (cookies[i].getName().equals("JCONTAINERID")) {
                        needContainerId = false;
                        break;
                    }
                }
            }
            if (needContainerId) {
                response.setContainerId(cacheElement.contextPath.toString());
            }
        }
    }

    /**This method returnes appropriate input stream depending on the request
     * parameters.
     * @return empty input stream for the requests without Conten-Length or
     * Transfer-Encoding headers or @see ChunkedServletInputStream class instance
     * with the socket intup stream inside for the requests with the chunked
     * transfer encoding or @see FixedLengthServletInputStream class instance
     * with the socket intup stream inside for the requests with the fixed
     * content length or null otherwise.
     */
    private NusuthServletInputStream retreiveInputStream() {
        int len = -1;
        try {
            len = Utils.retreiveContentLength(headers);
        } catch (IOException ioex) {
            //Logger.log(ioex, 1);
            cat.error("Bad request", ioex);
            good = false;
            usingStream = 0;
            return null;
        }
        if (!good) {
            usingStream = 0;
            return null;
        }
        if (len == -1) {
            if (requestLine.protocol.equals(http11)
                    && headers.containsHeader(HttpConstants.TRANSFER_ENCODING,
                            HttpConstants.CHUNKED)) {
                chunkedServletInput.init(inputStream);
                usingStream = 2;
                return chunkedServletInput;
            } else {
                nullServletInput.init(inputStream);
                return nullServletInput;
            }
        } else {
            contentLength = len;
            fixedServletInput.init(inputStream, len);
            usingStream = 1;
            return fixedServletInput;
        }
    }

