    public void cleanup() {
        partialCleanup();
        super.cleanup();
        inputStream.cleanup();
        outputStream = null;
        keepAliveAllowed = false;
    }

    public void partialCleanup() {
        if (successfullyParsed) {
            if (catPool.containsKey(hostHeader)) {
                AccessLogWrapper wrapper = (AccessLogWrapper) catPool.get(hostHeader);
                AccessLogger category = wrapper.getCategory();
                switch (wrapper.getLogType()) {

                    case AccessLogWrapper.TYPE_COMMON:
                        createCommonLog(wrapper.isResolve());
                        logMessage.append(systemCRLF);
                        category.log(logMessage);
                        break;

                    case AccessLogWrapper.TYPE_EXTENDED:
                        createCommonLog(wrapper.isResolve());
                        if (!headers.containsHeader(REFERER_HEADER_NAME)) {
                            logMessage.append(chars4log[3]);
                        } else {
                            logMessage.append(chars4log[1]);
                            headers.appendHeaderValue(REFERER_HEADER_NAME, logMessage);
                            logMessage.append('\"');
                        }
                        if (!headers.containsHeader(AGENT_HEADER_NAME)) {
                            logMessage.append(chars4log[3]);
                        } else {
                            logMessage.append(chars4log[1]);
                            headers.appendHeaderValue(AGENT_HEADER_NAME, logMessage);
                            logMessage.append('\"');
                        }
                        logMessage.append(systemCRLF);
                        category.log(logMessage);
                        break;

                    default:
                        break;
                }
            }
        }
        successfullyParsed = false;
        logMessage.clear();
        reqTime = null;
        contentLength = -1;
        host = null;
        errorCode = HttpServletResponse.SC_OK;
        hostHeader.clear();
        hostId.clear();
        hostWithUri.clear();
        request.cleanup();
        response.cleanup();
        headers.clear();
        scPath = null;
        requestURI = null;
        parameters.clear();
        switch (usingStream) {
            case 1:
                fixedServletInput.cleanup();
                break;
            case 2:
                chunkedServletInput.cleanup();
                break;
            default:
                break;
        }
        servletOutput.cleanup();
        inputStream.partialCleanup();
        requestLine.clear();
        serverHost = null;
        serverPort = -1;
    }

