    public Hashtable getParameters(String encoding) {
        if (requestLine.queryString.length() != 0) {
            try {
                parameters = Utils.parseQueryString(requestLine.queryString.toString(encoding));
            } catch (IllegalArgumentException iae) {
                cat.warn("Cannot parse query string " + requestLine.queryString);
            } catch (UnsupportedEncodingException uee) {
                cat.warn("Cannot decode query string " + requestLine.queryString);
            }
        }
        ServletInputStream is = request.getInputStream();
        Hashtable params = new Hashtable();
        if (getMethod().equals("POST") &&
                headers.containsHeader(HttpConstants.CONTENT_TYPE,
                        HttpConstants.WWW_FORM)) {
            try {
                Hashtable formprs
                        = parsePostData(Utils.retreiveContentLength(headers), is,
                                encoding);
                Enumeration enum = formprs.keys();
                String key;
                String[] urlValues;
                String[] postValues;
                String[] resValues;
                while (enum.hasMoreElements()) {
                    key = (String) enum.nextElement();
                    if (params.get(key) == null) {
                        params.put(key, formprs.get(key));
                    } else {
                        postValues = (String[]) formprs.get(key);
                        urlValues = (String[]) params.get(key);
                        resValues = new String[postValues.length + urlValues.length];
                        for (int i = 0; i < urlValues.length; i++) {
                            resValues[i] = urlValues[i];
                        }
                        for (int i = 0; i < postValues.length; i++) {
                            resValues[urlValues.length + i] = postValues[i];
                        }
                        params.put(key, resValues);
                    }
                }
                addParameters(params);
            } catch (IOException ioex) {
            }
        }
        return parameters;
    }

    protected void addParameters(Hashtable newParams) {
        Enumeration enum = newParams.keys();
        String[] oldParamSet;
        String[] newParamSet;
        String[] concatParamSet;
        String key;
        while (enum.hasMoreElements()) {
            key = (String) enum.nextElement();
            oldParamSet = (String[]) parameters.get(key);
            if (oldParamSet == null) {
                concatParamSet = (String[]) newParams.get(key);
            } else {
                newParamSet = (String[]) newParams.get(key);
                concatParamSet = new String[oldParamSet.length + newParamSet.length];
                System.arraycopy(newParamSet, 0, concatParamSet, 0, newParamSet.length);
                System.arraycopy(oldParamSet, 0, concatParamSet, newParamSet.length,
                        oldParamSet.length);
            }
            parameters.put(key, concatParamSet);
        }
    }

    /**
     * This method parse posted data.
     * @param len Length of data.
     * @param in InputStream with data.
     * @param encoding Character encoding to use.
     * @return Hashatable with parameters.
     */
    private Hashtable parsePostData(int len, ServletInputStream in,
                                    String encoding) {
        if (len <= 0)
            return new Hashtable();
        if (in == null)
            throw new IllegalArgumentException();
        byte postedBytes[] = new byte[len];
        try {
            int offset = 0;
            do {
                int inputLen = in.read(postedBytes, offset, len - offset);
                if (inputLen <= 0) {
                    String msg = lStrings.getString("err.io.short_read");
                    throw new IllegalArgumentException(msg);
                }
                offset += inputLen;
            } while (len - offset > 0);
        } catch (IOException e) {
            throw new IllegalArgumentException(e.getMessage());
        }
        try {
            return Utils.parseAndDecodeQuery(postedBytes, encoding);
        } catch (UnsupportedEncodingException e) {
            throw new IllegalArgumentException(e.getMessage());
        }
    }

