    public void sendRedirect(String location) throws IOException {
        try {
            servletOutput.init(outputStream);
            response.init(servletOutput, keepAlive);
            response.sendRedirect(location);
        } catch (IOException ioex) {
            //Logger.log("Error occured while writing error", ioex, 1);
            cat.error("Error occured while redirecting request");
        }
        //    response.sendRedirect(location);
    }

    public void sendRedirect(String scheme, int port) {
        String uri = (requestURI == null) ? requestLine.uri.toString() : requestURI;
        String query = requestLine.queryString.toString();
        query = (query.length() == 0) ? query : ("?" + query);
        try {
            servletOutput.init(outputStream);
            response.init(servletOutput, false);
            response.sendRedirect(scheme + "://" + getServerHost() + ":" + port + uri + query);
        } catch (IOException e) {
            cat.error("Error occured while redirecting request");
        }
    }

    public void processUnavailable(int seconds, String message) {
        response.reset();
        response.setStatus(503);
        if (seconds != -1)
            response.setIntHeader("Retry-After", seconds);
        ServletOutputStream out = response.getOutputStream();
        try {
            out.println("<H1> 503 " + response.getErrorDescription(503) + "</H1>");
            out.println("<BR>");
            if (seconds != -1)
                out.println("Service unavailable for " + seconds + " seconds");
            else
                out.println("Service unavailable permanently");
            out.println("<BR>");
            out.println(message);
        } catch (IOException ex) {
        }
    }

    private void retrieveServerParameters() {
        String hostHeader = headers.getHeader("Host");
        if (hostHeader != null) {
            int scIndex = hostHeader.indexOf(':');
            serverHost = scIndex == -1 ? hostHeader : hostHeader.substring(0, scIndex);
            try {
                serverPort = scIndex == -1 ? isSecure ? 443 : 80 : Integer.parseInt(hostHeader.substring(scIndex + 1));
            } catch (Exception ex) {
                cat.warn(ex);
            }
        } else {
            serverHost = super.getServerHost() == null ? headers.getHeader("Server-Host") : super.getServerHost();
            serverPort = super.getServerPort() == -1 ? headers.getIntHeader("Server-Port") : super.getServerPort();
        }
    }

