    public StrBuffer getSecretKeyCandidate() {
        return getRequestURI();
    }

    /**
     * This method return requested host.
     * @return Requested host or "*" if request not contains Host header.
     */
    public String getHost() {
        headers.appendHeaderValue(HOST_HEADER_NAME, hostId);
        hostId.cutToChar(':', false);
        if (hostId.length() != 0) {
            if (!allHosts.contains(hostId)) {
                hostId.clear();
                hostId.append('*');
                ;
            }
        } else {
            hostId.append('*');
        }
        return hostId.toString();
    }


    /**
     * This method return StrBuffer that contains information about requestded
     * host and uri.
     * @return Host with URI.
     */
    public StrBuffer getHostWithUri() {
        hostWithUri.clear();
        headers.appendHeaderValue(HOST_HEADER_NAME, hostWithUri);
        hostWithUri.cutToChar(':', false);
        if (hostWithUri.length() != 0) {
            if (!allHosts.contains(hostWithUri)) {
                hostWithUri.clear();
                hostWithUri.append('*');
                ;
            }
        } else {
            hostWithUri.append('*');
        }
        hostHeader.append(hostWithUri);
        hostWithUri.append(getRequestURI());
        return hostWithUri;
    }

    public static void setAllHosts(HashSet hosts) {
        allHosts = hosts;
    }

    public void writeDeny() {
        servletOutput.init(outputStream);
        response.init(servletOutput, false);
        try {
            response.sendError(403, "You do not have permission to access this server");
        } catch (IOException ioex) {
            cat.debug("Error occured while sending deny", ioex);
        }
    }

    private void createCommonLog(boolean resolve) {
        logMessage.append((resolve) ? getHostName() : getHostAddress());
        logMessage.append(chars4log[0]);
        logMessage.append(reqTime);
        logMessage.append(chars4log[1]);
        logMessage.append(requestLine.method);
        logMessage.append(' ');
        logMessage.append(requestLine.uri);
        if (requestLine.queryString.length() > 0) {
            logMessage.append('?');
            logMessage.append(requestLine.queryString.toString());
        }
        logMessage.append(' ');
        logMessage.append(requestLine.protocol);
        logMessage.append(chars4log[2]);
        logMessage.appendInt(response.getStatusCode());
        logMessage.append(' ');
        logMessage.appendInt(response.getNumberOfBytesTransfered());
    }

    // added by igork

    public ResourceSecurityRecord getResourceSecurityRecord() {
        StrBuffer resourcePath = new StrBuffer(cacheElement.servletPath.length() + 1 + cacheElement.pathInfo.length());
        resourcePath.append(cacheElement.servletPath);
        if (cacheElement.servletPath.length() > 0 && cacheElement.pathInfo.length() > 0 && !cacheElement.pathInfo.startsWith(slash))
            resourcePath.append('/');
        resourcePath.append(cacheElement.pathInfo);
        if (resourcePath.length() == 0)
            resourcePath.append('/');
        return new ResourceSecurityRecord(resourcePath, requestLine.method);
    }

    public void saveRequest() {
        NusuthSession session = (NusuthSession) request.getSession(true);
        String queryStringToSave = request.getQueryString() == null || request.getQueryString().length() == 0 ? "" : '?' + request.getQueryString();
        String urlToSave = (request.isSecure() ? "https://" : "http://") + getServerHost() + ':' + getServerPort() + getRequestURI() + queryStringToSave;
        session.saveUrl(urlToSave);
    }

    public void restoreRequest() {
        NusuthSession session = (NusuthSession) request.getSession(true);
        String url = session.getSavedUrl();
        if (url != null) {
            try {
                sendRedirect(url);
            } catch (IOException ioex) {
                cat.debug("Couldn't redirect to original URL after login", ioex);
            }
            /*request = state.savedRequest;
             requestLine = state.savedRequestLine;
             requestURI = null;
             response.setHeader("Location", requestLine.uri.toString());
             setContext(state.savedContext, state.savedContextPath);*/
            session.clearSavedUrl();
        }
    }

